/*
 * A021062  Decimal expansion of 1/58.
 * https://oeis.org/A021062
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons, easy
 * Formula:   not stated
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(0) = 0.
 * For n ≥ 1, a(n) is the nth digit of the decimal expansion of 1/58
 * after the initial zero following the decimal point.
 * The sequence is generated by long division (1 / 58), skipping the
 * first zero after the decimal point.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    if (n == 0)
        return 0;

    /* static state for memoisation */
    static seq_t *cache = NULL;        /* stored digits after skipping zero */
    static size_t cache_cap = 0;
    static size_t cache_len = 0;      /* number of stored digits (≥ 0) */
    static uint64_t rem = 1;          /* remainder after integer part */

    /* initialise cache on first call */
    if (!cache) {
        cache_cap = 64;
        cache = (seq_t *)malloc(sizeof(seq_t) * cache_cap);
        if (!cache) return 0; /* allocation failure – not expected */
    }

    /* generate digits until we have at least n digits (after zero skip) */
    while (cache_len < (size_t)n) {
        /* compute next decimal digit */
        uint64_t digit = (rem * 10) / 58;
        rem = (rem * 10) % 58;

        /* skip the very first zero after the decimal point */
        if (cache_len == 0 && digit == 0)
            continue;

        /* ensure space in cache */
        if (cache_len >= cache_cap) {
            size_t new_cap = cache_cap * 2;
            seq_t *new_cache = (seq_t *)realloc(cache, sizeof(seq_t) * new_cap);
            if (!new_cache) return 0; /* allocation failure – not expected */
            cache = new_cache;
            cache_cap = new_cap;
        }

        cache[cache_len] = (seq_t)digit;
        ++cache_len;
    }

    /* n ≥ 1, so index is n‑1 in the cache */
    return cache[n - 1];
}
